def largest_smallest_integers(lst):
    negative_integers = []
    positive_integers = []

    for num in lst:
        if num < 0:
            negative_integers.append(num)
        elif num > 0:
            positive_integers.append(num)

    if not negative_integers:
        a = None
    else:
        a = max(negative_integers)  # largest negative integer

    if not positive_integers:
        b = None
    else:
        b = min(positive_integers)  # smallest positive integer

    return (a, b)
